			case "symbolic leaf", "hard link":
				outside := filepath.Join(t.TempDir(), "source.py")
				write468(t, filepath.Dir(outside), "source.py", p.Sources[file])
				if err := os.Remove(leaf); err != nil {
					t.Fatal(err)
